import{_ as a,c as e,o as d,b0 as o}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/layers-encapsulation.BGJ1DBY4.svg",P=JSON.parse('{"title":"LV001-网络分层模型与TCP-IP协议栈","description":null,"frontmatter":{"title":"LV001-网络分层模型与TCP-IP协议栈","date":"2026-10-14T21:56:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb0077c57a0b5fb","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:56:00.119Z","fulluuid":"c57a0b5fb22d472fba17aee8f023fea3","useduuid":"c57a0b5fb"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb0077c57a0b5fb.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV001-网络分层模型与TCP-IP协议栈.md","lastUpdated":1792231946000}'),c={name:"sdoc/advanced-chapter/network-basics/126d628e1bb0077c57a0b5fb.md"};function s(n,t,l,i,p,h){return d(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="lv001-网络分层模型与tcp-ip协议栈" tabindex="-1">LV001-网络分层模型与TCP-IP协议栈 <a class="header-anchor" href="#lv001-网络分层模型与tcp-ip协议栈" aria-label="Permalink to &quot;LV001-网络分层模型与TCP-IP协议栈&quot;">​</a></h1><h2 id="一、-网络为什么要分层" tabindex="-1">一、 网络为什么要分层 <a class="header-anchor" href="#一、-网络为什么要分层" aria-label="Permalink to &quot;一、 网络为什么要分层&quot;">​</a></h2><h3 id="_1-一次性解决所有问题是不现实的" tabindex="-1">1. 一次性解决所有问题是不现实的 <a class="header-anchor" href="#_1-一次性解决所有问题是不现实的" aria-label="Permalink to &quot;1. 一次性解决所有问题是不现实的&quot;">​</a></h3><p>两台设备要通信，要解决的问题有一大堆：</p><ul><li>物理层：用几伏电压表示 0 和 1，用几根线，双绞还是同轴；</li><li>链路层：怎么把一串比特划成一段一段的帧，怎么知道帧的开头和结尾，出错了要不要重传；</li><li>网络层：怎么在成百上千台设备里找到目标，怎么跨过一段又一段的链路；</li><li>传输层：数据丢了好不好重传，谁先发谁后发，对方来不及收怎么办；</li><li>应用层：对方拿到的字节流到底该怎么理解，是文件、是网页还是一句命令。</li></ul><p>把这五类问题<strong>一次性全解决</strong>是不现实的：它们彼此的关注点完全不同，混在一起写，任何一处改动都会牵动全部。</p><p>工程上的做法是<strong>分层</strong>：每一层只解决一类问题，只跟自己的上下层打交道。</p><h3 id="_2-分层带来的三个好处" tabindex="-1">2. 分层带来的三个好处 <a class="header-anchor" href="#_2-分层带来的三个好处" aria-label="Permalink to &quot;2. 分层带来的三个好处&quot;">​</a></h3><p>（1）<strong>换硬件不影响上层</strong>。这块板子用的是 DM9000 网卡，换一颗别的网卡芯片，TCP/IP 以上的部分一行都不用改。</p><p>（2）<strong>换应用不影响下层</strong>。今天跑 TFTP 拉固件，明天跑 HTTP 传网页，底下的 TCP/IP 与网卡驱动都不动。</p><p>（3）<strong>每层的责任清晰，出问题能按层排查</strong>。这也是后面查网络故障时&quot;从物理往上逐层砍&quot;这个思路的由来：先看网口灯，再看网卡 ID，再看地址，再看 ARP，最后才怀疑协议栈。</p><h3 id="_3-分层的代价" tabindex="-1">3. 分层的代价 <a class="header-anchor" href="#_3-分层的代价" aria-label="Permalink to &quot;3. 分层的代价&quot;">​</a></h3><p>分层不是免费的，代价主要有两条：</p><ul><li><strong>首部开销</strong>：每往下走一层就加一个头部。一个 ping 包真正想传的数据可能只有 8 字节，实际在网线上跑的却有 42 字节以上。</li><li><strong>层间复制与查表</strong>：每层的收发都要有自己的缓冲、查表与状态机，对内存只有 64 KB 的 STM32F103 来说，这些都是要精打细算的开支。</li></ul><p>本工程的做法是&quot;要分层，但每一层都裁到刚好够用&quot;——这正是后面 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51d3a6f2be804.html">LV015-lwIP配置与初始化</a> 里那张 <code>lwipopts.h</code> 裁剪表的由来。</p><h2 id="二、-两种分层模型" tabindex="-1">二、 两种分层模型 <a class="header-anchor" href="#二、-两种分层模型" aria-label="Permalink to &quot;二、 两种分层模型&quot;">​</a></h2><h3 id="_1-osi-七层与-tcp-ip-四层的对应" tabindex="-1">1. OSI 七层与 TCP/IP 四层的对应 <a class="header-anchor" href="#_1-osi-七层与-tcp-ip-四层的对应" aria-label="Permalink to &quot;1. OSI 七层与 TCP/IP 四层的对应&quot;">​</a></h3><p>教材里最常出现的是 OSI 七层模型，而实际互联网跑的是 TCP/IP 四层模型。两者的对应关系如下：</p><table tabindex="0"><thead><tr><th>OSI 七层</th><th>TCP/IP 四层</th><th>这一层负责什么</th><th>典型协议 / 设备</th></tr></thead><tbody><tr><td>应用层、表示层、会话层</td><td><strong>应用层</strong></td><td>面向具体业务</td><td>HTTP、DNS、TFTP、DHCP</td></tr><tr><td>传输层</td><td><strong>传输层</strong></td><td>进程到进程（靠端口区分）</td><td>TCP、UDP</td></tr><tr><td>网络层</td><td><strong>网络层</strong>（网际层）</td><td>主机到主机（跨网段寻址）</td><td>IP、ICMP</td></tr><tr><td>数据链路层、物理层</td><td><strong>网络接口层</strong></td><td>一跳之内（同一条链路）</td><td>以太网、MAC、PHY</td></tr></tbody></table><p>如果按 OSI 的七层展开，从上到下依次是：应用层、表示层、会话层、传输层、网络层、数据链路层、物理层。</p><h3 id="_2-为什么实际只谈四层" tabindex="-1">2. 为什么实际只谈四层 <a class="header-anchor" href="#_2-为什么实际只谈四层" aria-label="Permalink to &quot;2. 为什么实际只谈四层&quot;">​</a></h3><p>OSI 的&quot;表示层、会话层&quot;在 TCP/IP 里被并进应用层了。原因是这两层在实际实现中很难划出清晰的边界：数据怎么编码（表示层）通常由具体应用自己决定，而&quot;会话&quot;的概念更多落在应用自己的状态机里。</p><p>所以实际写代码时基本只谈四层，本系列文档也统一按四层展开。</p><h3 id="_3-一处归属争议-arp-属于哪一层" tabindex="-1">3. 一处归属争议：ARP 属于哪一层 <a class="header-anchor" href="#_3-一处归属争议-arp-属于哪一层" aria-label="Permalink to &quot;3. 一处归属争议：ARP 属于哪一层&quot;">​</a></h3><p>教材里对 ARP 的说法不统一：</p><ul><li>它报文的承载方式<strong>属于数据链路层</strong>——ARP 报文直接封在以太网帧里跑，帧类型字段是 <code>0x0806</code>；</li><li>它干的事情却是<strong>为网络层服务</strong>——把 IP 地址解析成 MAC 地址。</li></ul><p>所以更准确的理解是<strong>夹在网络层与网络接口层之间</strong>。本系列把它放在 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030-ARP与MAC地址</a> 单独讲，讲完再看归属问题会清楚得多。</p><h2 id="三、-数据是怎么一层层封装起来的" tabindex="-1">三、 数据是怎么一层层封装起来的 <a class="header-anchor" href="#三、-数据是怎么一层层封装起来的" aria-label="Permalink to &quot;三、 数据是怎么一层层封装起来的&quot;">​</a></h2><h3 id="_1-发送加头、接收脱头" tabindex="-1">1. 发送加头、接收脱头 <a class="header-anchor" href="#_1-发送加头、接收脱头" aria-label="Permalink to &quot;1. 发送加头、接收脱头&quot;">​</a></h3><p>发数据是从上往下逐层加头，收数据是从下往上逐层脱头：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送方向 ↓                                   接收方向 ↑</span></span>
<span class="line"><span>应用层        应用数据                          应用数据</span></span>
<span class="line"><span>传输层        [TCP头][应用数据]                  脱 TCP 头</span></span>
<span class="line"><span>网络层        [IP头][TCP头][应用数据]            脱 IP 头</span></span>
<span class="line"><span>链路层        [以太网头][IP头][TCP头][数据][校验] 脱以太网头</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>每一次&quot;加头&quot;就是一次<strong>封装</strong>，每一次&quot;脱头&quot;就是一次<strong>解封装</strong>。</p><img src="`+r+'" alt="TCP/IP 分层与数据封装过程"><p>帧里每一个字段具体占几个字节、校验覆盖哪一段，<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb00a1f4c6d9e02.html">LV005-数据封装与以太网帧</a> 会逐个字段拆开讲，这里先看整体形态。</p><h3 id="_2-一次-ping-的报文拆解" tabindex="-1">2. 一次 ping 的报文拆解 <a class="header-anchor" href="#_2-一次-ping-的报文拆解" aria-label="Permalink to &quot;2. 一次 ping 的报文拆解&quot;">​</a></h3><p>以一次 ping 为例，板子收到的报文会长这样：</p><table tabindex="0"><thead><tr><th>部分</th><th>长度</th><th>内容</th></tr></thead><tbody><tr><td>以太网头</td><td>14 字节</td><td>目的 MAC、源 MAC、类型（<code>0x0800</code> 表示里面装的是 IPv4）</td></tr><tr><td>IP 头</td><td>20 字节</td><td>版本、总长、源 IP、目的 IP、协议号（1 表示 ICMP）……</td></tr><tr><td>ICMP 报文</td><td>8 字节起</td><td>类型（8 = 请求，0 = 应答）、校验和、标识、序号、数据</td></tr></tbody></table><h3 id="_3-三种地址各自管多远" tabindex="-1">3. 三种地址各自管多远 <a class="header-anchor" href="#_3-三种地址各自管多远" aria-label="Permalink to &quot;3. 三种地址各自管多远&quot;">​</a></h3><p>链路层最大的一个特点：<strong>以太网头里的 MAC 地址只在一跳之内有效</strong>，每经过一台路由器就会被重写一次；而 IP 头里的地址是端到端的，一路不变。</p><p>把三种地址摆在一起看最清楚：</p><table tabindex="0"><thead><tr><th>地址</th><th>工作在哪一层</th><th>作用范围</th></tr></thead><tbody><tr><td>MAC 地址</td><td>数据链路层</td><td>一跳之内，换一个路由器就变了</td></tr><tr><td>IP 地址</td><td>网络层</td><td>端到端，全程不变</td></tr><tr><td>端口号</td><td>传输层</td><td>同一台主机上区分是哪个程序</td></tr></tbody></table><p>一句话概括：<strong>MAC 找到&quot;下一跳的那台设备&quot;，IP 找到&quot;最终的那台设备&quot;，端口找到&quot;那台设备上的哪个程序&quot;</strong>。</p><p>跨网段时这两种地址的表现差异会成为一个关键结论，见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015-网关与跨网段通信</a> 第三节。</p><h2 id="四、-把分层映射到-lwip-的源码目录" tabindex="-1">四、 把分层映射到 lwIP 的源码目录 <a class="header-anchor" href="#四、-把分层映射到-lwip-的源码目录" aria-label="Permalink to &quot;四、 把分层映射到 lwIP 的源码目录&quot;">​</a></h2><h3 id="_1-分层与文件的对照表" tabindex="-1">1. 分层与文件的对照表 <a class="header-anchor" href="#_1-分层与文件的对照表" aria-label="Permalink to &quot;1. 分层与文件的对照表&quot;">​</a></h3><p>本项目用的 lwIP 2.1.3（<code>atk-f103/Components/lwip-2.1.3/</code>）目录结构与四层模型几乎是直译的：</p><table tabindex="0"><thead><tr><th>分层</th><th>本工程中的文件</th><th>说明</th></tr></thead><tbody><tr><td>应用层</td><td><code>port/iap_tcp.c</code>、<code>Drivers/BSP/Ota/ota_tftp.c</code></td><td>自己写的 TCP 服务器与 TFTP 客户端</td></tr><tr><td>传输层</td><td><code>src/core/tcp.c</code>、<code>tcp_in.c</code>、<code>tcp_out.c</code>、<code>udp.c</code></td><td>TCP/UDP 的实现</td></tr><tr><td>网络层</td><td><code>src/core/ipv4/ip4.c</code>、<code>ip4_addr.c</code>、<code>icmp.c</code>、<code>etharp.c</code></td><td>IP 收发、地址处理、ICMP、ARP</td></tr><tr><td>网络接口层</td><td><code>port/ethernetif.c</code> + <code>Drivers/BSP/Ethernet/dm9000.c</code></td><td>lwIP 与网卡的接口 + 网卡驱动本身</td></tr><tr><td>平台适配</td><td><code>port/lwipopts.h</code>、<code>port/sys_arch.c</code>、<code>port/arch/cc.h</code></td><td>不属于某一层，服务于整个协议栈</td></tr></tbody></table><h3 id="_2-后面几篇各讲哪个文件" tabindex="-1">2. 后面几篇各讲哪个文件 <a class="header-anchor" href="#_2-后面几篇各讲哪个文件" aria-label="Permalink to &quot;2. 后面几篇各讲哪个文件&quot;">​</a></h3><p>记住上面这张表，&quot;读哪一篇对应哪个文件&quot;就清楚了：</p><p>（1）<strong>地址与掩码</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0119ba6c38b7d.html">LV010-IP地址与子网掩码</a>）→ <code>ip4_addr.c</code>。</p><p>（2）<strong>交换机、路由器与网关</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0169159fefb70.html">LV020</a>、<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015</a>）→ 主要是硬件侧的事，协议栈里没有直接对应文件。</p><p>（3）<strong>ARP</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030</a>）→ <code>etharp.c</code>。</p><p>（4）<strong>传输层：端口、UDP 与 TCP</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035</a>）→ <code>tcp.c</code>、<code>tcp_in.c</code>、<code>tcp_out.c</code>、<code>udp.c</code>。</p><p>（5）<strong>DHCP</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.html">LV040</a>）→ <code>src/core/ipv4/dhcp.c</code>，本工程把它裁掉了，只做源码对照。</p><p>（6）<strong>网络调试工具</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b.html">LV045</a>）→ 工具侧的事，与决策树搭配用。</p><p>（7）<strong>一次 ping 的全过程</strong>（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050</a>）→ 串起 <code>icmp.c</code>、<code>ip4.c</code>、<code>etharp.c</code>、<code>ethernetif.c</code>。</p><h3 id="_3-两个术语的用法" tabindex="-1">3. 两个术语的用法 <a class="header-anchor" href="#_3-两个术语的用法" aria-label="Permalink to &quot;3. 两个术语的用法&quot;">​</a></h3><p>&quot;TCP/IP&quot;这个词有两种用法，读到时要看语境：</p><p>（1）狭义：指 TCP 和 IP 这两个协议本身。</p><p>（2）广义：指整套协议族（TCP/IP 协议栈），包含 IP、TCP、UDP、ICMP、ARP 等等。</p><p>lwIP 这个名字是 &quot;lightweight IP&quot; 的缩写，但它是一整套协议栈，不只是 IP 协议。</p><h2 id="五、-小结与参考资料" tabindex="-1">五、 小结与参考资料 <a class="header-anchor" href="#五、-小结与参考资料" aria-label="Permalink to &quot;五、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>网络分层是为了&quot;每层只解决一类问题&quot;，也让排错可以按层逐段缩小范围；代价是首部开销与层间缓冲。</li><li>OSI 七层与实际用的 TCP/IP 四层可以对照，OSI 的上三层对应 TCP/IP 的应用层。</li><li>发数据是逐层加头（封装），收数据是逐层脱头（解封装）。</li><li>四层里每一层用不同的地址：MAC 管一跳、IP 管端到端、端口管进程。</li><li>以太网帧类型字段是分流的依据：<code>0x0806</code> → ARP，<code>0x0800</code> → IPv4。</li><li>lwIP 的目录结构就是这套分层的直接映射，后面的文档都围绕这张表展开。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>lwIP 源码目录：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/tree/main/atk-f103/Components/lwip-2.1.3" target="_blank" rel="noreferrer"><code>atk-f103/Components/lwip-2.1.3/</code></a></li><li>网卡接口层：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/ethernetif.c" target="_blank" rel="noreferrer"><code>ethernetif.c</code></a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.4 节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',68)])])}const u=a(c,[["render",s]]);export{P as __pageData,u as default};
